<?php $pageTitle='Resumen'; require __DIR__.'/_header.php';$counts=[];$statuses=['received','awaiting_receipt','receipt_received','paid','preparing','on_the_way','delivered'];foreach($statuses as $st){$q=db()->prepare('SELECT COUNT(*) FROM orders WHERE status=?');$q->execute([$st]);$counts[$st]=(int)$q->fetchColumn();}$today=(float)db()->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE DATE(created_at)=CURDATE() AND status<>'cancelled'")->fetchColumn();$recent=db()->query('SELECT * FROM orders ORDER BY id DESC LIMIT 8')->fetchAll();?><div class="admin-grid stats"><div><span>Pedidos hoy</span><b><?=h((string)db()->query('SELECT COUNT(*) FROM orders WHERE DATE(created_at)=CURDATE()')->fetchColumn())?></b></div><div><span>Comprobantes</span><b><?=$counts['receipt_received']?></b></div><div><span>En preparación</span><b><?=$counts['preparing']?></b></div><div><span>Ventas hoy</span><b><?=money($today)?></b></div></div><section class="admin-card"><div class="admin-card-head"><h2>Pedidos recientes</h2><a href="orders.php">Ver todos</a></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($recent as $o):?><tr><td><?=h($o['public_id'])?></td><td><?=h($o['customer_name'])?></td><td><?=money((float)$o['total'])?></td><td><span class="status-pill"><?=h($o['status'])?></span></td><td><a href="order.php?id=<?=$o['id']?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>